      "summary": "Chardonnay is the world's most widely planted and arguably most versatile noble white grape, capable of producing everything from lean, mineral still wines to rich, oaked blockbusters to the backbone of the world's finest sparkling wines. It is prized for its neutrality, which allows it to transmit terroir and winemaking choices with unusual clarity, and for its adaptability to almost any climate.",
