      "characteristics": "Chardonnay is often described as a relatively neutral variety, meaning climate, site and winemaking exert an outsized influence on its final character. In cool climates it shows green apple, lemon, and white flower notes with high, sometimes searing acidity and a lean body; in warm climates it ripens into peach, melon, fig, and tropical fruit flavours with fuller body, lower acidity, and higher potential alcohol. Malolactic conversion adds a buttery, creamy quality, while oak ageing contributes vanilla, toast, and spice, so the same base fruit can taste dramatically different depending on cellar choices.",
