      "summary": "Verdicchio is the signature white grape of the Marche region, prized for its high acidity, distinctive bitter almond note, and unusually strong ageing potential among mainstream Italian whites. It is best known through the Castelli di Jesi and Matelica appellations.",
      "viticulture": "Verdicchio is a late-ripening variety that reliably retains high acidity and benefits from a long, slow ripening period on hillside sites in the Marche, which supports both aromatic and phenolic development. It is moderately vigorous with a reasonably thick skin that lends some resilience to disease pressure, and it performs particularly well in the cooler, more continental-influenced Matelica valley as well as the Castelli di Jesi hills.",
