      "origin": "Mediterranean, likely Italy or Spain",
      "summary": "Vermentino is a Mediterranean white grape prized for its fresh, saline character and ability to thrive in hot, windy coastal conditions. It is the signature white of Sardinia and Liguria in Italy and also widely planted in Corsica and southern France as Rolle. Styles range from light and zesty to richer, textured examples from old vines.",
      "viticulture": "Vermentino is a vigorous, warm-climate variety that buds and ripens in the mid-season, performing best in coastal or Mediterranean sites where sea breezes moderate heat and help preserve acidity. It tolerates drought and wind well, making it suited to bush-trained or low-trellised vines on poor, sandy or granitic soils, and it shows good resistance to downy mildew but can be susceptible to powdery mildew and botrytis in humid conditions. Yields can be generous if not controlled, which risks dilution, so growers often restrict canopy vigour and crop levels to concentrate flavour and retain the grape's characteristic freshness.",
      "characteristics": "In cooler coastal sites Vermentino shows citrus, green apple, and white flower aromas with a distinctive saline or flinty minerality and sometimes a faint bitter almond note on the finish. In warmer or riper expressions it develops riper stone fruit, fennel, and herbal notes with fuller body. Acidity is medium to high, giving the wines their characteristic freshness, while alcohol is typically medium to medium-plus; body ranges from light to medium depending on site and winemaking choices.",
      "winemaking": "Vermentino is most commonly vinified as a dry, unoaked white using stainless steel to preserve its aromatic freshness and minerality, though premium examples—particularly from Liguria's Pigato or old-vine Sardinian sites—may see partial oak fermentation or ageing and lees contact (bâtonnage) to add texture and complexity. Malolactic conversion is generally avoided or only partially used to retain acidity. In Provence and Corsica it is frequently blended with Ugni Blanc, Clairette, or Grenache Blanc as Rolle, while in Italy it is usually bottled as a varietal wine.",
