      "origin": "Austria",
      "summary": "Grüner Veltliner is Austria's flagship white grape, producing everything from light, peppery everyday wines to concentrated, age-worthy examples from top sites like the Wachau. It is known for its distinctive white pepper spice, citrus and stone fruit character, and often a vegetal, lentil-like note.",
      "viticulture": "Grüner Veltliner is a mid to late-budding, mid to late-ripening variety suited to cool to moderate continental climates, and it is planted extensively along the Danube river terraces where diurnal temperature swings preserve acidity. It is a vigorous variety that requires careful canopy management and crop thinning to avoid overcropping, and it prefers well-drained loess, primary rock, or gravelly soils. It is moderately susceptible to fungal diseases and frost in low-lying sites, and top examples come from terraced vineyards with significant diurnal range.",
      "characteristics": "The grape's signature is white pepper spice alongside citrus, green apple, and stone fruit, often layered with a distinctive vegetal note reminiscent of lentils or white asparagus, and a mineral or flinty edge in cooler sites. Riper, warmer-climate or late-harvested examples show riper orchard and tropical fruit with less overt pepperiness and fuller body. Acidity is typically medium-plus to high, body ranges from light to full depending on ripeness and winemaking, and alcohol can range from moderate in everyday styles to high in top Smaragd-level wines.",
      "winemaking": "Most Grüner Veltliner is vinified in stainless steel to preserve freshness and peppery aromatics, though top examples, especially from the Wachau, Kamptal, and Kremstal, may use large old oak casks for fermentation or ageing to add texture without imparting overt oak flavour. Lees contact is common to build mid-palate weight, while malolactic conversion is generally avoided to retain the grape's fresh, spicy profile. It is usually bottled as a single varietal wine and is rarely blended.",
