      "viticulture": "Torrontés Riojano (the most planted of the Torrontés varieties) thrives in high-altitude, warm, dry desert climates such as Salta and La Rioja provinces, where intense sunlight is balanced by cool nights that preserve acidity and aromatic intensity. It buds and ripens in the mid-season and is moderately vigorous; because it is prone to sunburn and can lose acidity quickly if left too long on the vine, careful timing of harvest is important. It prefers sandy, well-drained soils and benefits from irrigation in Argentina's arid growing regions.",
      "characteristics": "Torrontés is intensely aromatic, showing pronounced notes of orange blossom, jasmine, rose petal, and Muscat grape alongside citrus and peach, giving an impression of sweetness on the nose despite being made dry. On the palate it is typically light to medium-bodied with medium to medium-plus acidity, and a notable textural or slightly bitter, oily quality on the finish that keeps the wine from tasting cloying. Alcohol is usually moderate, and high-altitude examples from Cafayate show the most vivid aromatics and freshness.",
      "winemaking": "Torrontés is almost always vinified as a dry, unoaked white, fermented cool in stainless steel to capture and preserve its intense floral aromatics; skin contact is generally minimal or brief to avoid excessive bitterness, though some producers use short maceration to add texture. Malolactic conversion and oak ageing are rare, as they would mute the grape's aromatic character. It is typically bottled as a varietal wine and drunk young, though a small number of producers experiment with skin-fermented or barrel-aged versions for added complexity.",
