      "viticulture": "Despite its pink skin, Moschofilero is vinified as a white (or sometimes rosé/sparkling) grape and performs best in cool, high-altitude sites, notably the Mantinia plateau at around 600-650 metres, where cooler temperatures preserve its delicate aromatics and acidity. It is an early to mid-budding, relatively vigorous variety that benefits from altitude-driven diurnal temperature variation, and it can be prone to poor fruit set (coulure) and needs careful canopy management to avoid excessive vigour diluting its aromatic intensity.",
      "characteristics": "Moschofilero is highly aromatic, showing pronounced rose petal, geranium, and citrus blossom notes alongside spice and a light musky, Muscat-like character, giving it an aromatic profile that can suggest sweetness despite typically being made dry. On the palate it is light-bodied with high, crisp acidity and often light natural spritz, with delicate citrus and white flower flavours; alcohol tends to be low to moderate, contributing to its reputation as a refreshing, easy-drinking style.",
      "winemaking": "Because Moschofilero's skin has a pink-grey tint, gentle, quick pressing is used to avoid extracting colour and phenolics when making white wine, and fermentation is typically cool in stainless steel to preserve its floral aromatics. It is also used to make rosé and, taking advantage of its natural acidity, traditional method or tank method sparkling wines. Oak ageing and malolactic conversion are rarely used, as they would dull the grape's delicate perfume and freshness.",
