      "viticulture": "Because 'Malvasia' covers numerous genetically distinct varieties, growing habits vary considerably, but many strains share a preference for warm, sunny Mediterranean climates, moderate to high vigour, and susceptibility to oxidation-prone overripening if not managed carefully. Various Malvasia types are grown from Madeira and the Canary Islands to Italy, Croatia, and Spain, with some strains (like Malvasia Istriana) adapted to cooler coastal conditions and others favouring hot, dry island climates ideal for late-harvest and fortified production. Many strains bud and ripen mid-season and are moderately susceptible to powdery mildew and botrytis, the latter sometimes encouraged deliberately for sweet wine production.",
