      "viticulture": "Vernaccia di San Gimignano (the Tuscan grape) is a moderately vigorous, mid-ripening variety well suited to the hilly, well-drained clay and sandstone soils around San Gimignano, benefiting from good sun exposure and moderate altitude for freshness. It requires reasonably warm conditions to ripen fully but can lose aromatic definition if overcropped, so yield control is important for quality-focused production. The Sardinian Vernaccia di Oristano, a genetically distinct grape, thrives in the hot Tirso river valley and is often left to ripen to high sugar levels for its oxidative, sherry-like wine style.",
      "characteristics": "Vernaccia di San Gimignano typically shows citrus, green apple, and white flower aromas with a distinctive savoury, almost saline or nutty bitterness on the finish, medium body, and medium-plus acidity. Sardinia's Vernaccia di Oristano, made in an oxidative, flor-influenced style similar to Sherry, develops deep notes of walnut, dried fruit, and a pungent, tangy character with high alcohol. The two wines share only a name; their sensory profiles are entirely different.",
