      "viticulture": "Verdejo is a mid-budding, mid to late-ripening variety well suited to Rueda's high-altitude, continental climate, where hot days and cool nights preserve its aromatic freshness and acidity. It has moderate vigour and prefers the region's sandy, stony soils, which offer good drainage and help limit yields naturally. It can be susceptible to powdery mildew and, given its thin skin, botrytis in humid conditions, and old, ungrafted bush vines are still found in parts of Rueda, contributing to some of the region's most concentrated examples.",
