      "summary": "Airén is a historically important, extremely drought-tolerant white grape from central Spain, long the world's most planted white variety by area due to its dominance in Castilla-La Mancha. It typically produces neutral, light, everyday wines, though old-vine, well-made examples can show more character.",
      "viticulture": "Airén is exceptionally well adapted to the hot, dry, continental climate and poor soils of La Mancha, showing remarkable drought tolerance thanks to a deep root system, which historically allowed it to be grown without irrigation in one of Europe's most arid wine regions. It is traditionally grown as low, widely spaced bush vines to maximise access to scarce water and minimise competition, and it buds and ripens in the mid-season with generally good disease resistance, though modern trellising and irrigation have also become common in commercial plantings.",
      "characteristics": "Airén typically produces fairly neutral wines with light citrus and green apple notes, low aromatic intensity, and low to medium acidity, especially in hot, high-yielding vineyards where it is often used for bulk or distillation purposes. Well-farmed, lower-yielding, and cooler-site examples can show a bit more freshness and delicate floral character, but the grape is generally not regarded as capable of great complexity. Alcohol levels tend to be moderate to high given the region's heat, and body is typically light to medium.",
