      "viticulture": "Macabeo/Viura is a vigorous, productive variety adapted to a range of climates from the warm, dry conditions of Catalonia to the more continental climate of Rioja, and it buds and ripens relatively early to mid-season. It retains good acidity even in warm conditions, a key reason for its importance in Cava production, and it is moderately resistant to disease though can be susceptible to powdery mildew; it performs well across a range of soil types but favours well-drained sites to control its naturally generous yields.",
