      "viticulture": "Xarel-lo is a vigorous, productive variety well suited to the warm, dry Mediterranean climate of Penedès, where it typically buds early and ripens in the mid-to-late season; it retains acidity relatively well compared to Macabeo despite the heat, partly because growers plant it on cooler, higher-altitude sites. It is naturally tolerant of drought, though downy mildew is a concern in damp years, and its thick skins give some resistance to disease pressure. Yields can be high if not controlled, diluting concentration, so quality producers restrict cropping levels. It performs best on the region's characteristic pale, calcareous soils.",
      "characteristics": "In the glass Xarel-lo shows notes of green apple, lemon, fennel and a distinctive herbal, slightly waxy or saline character, often described as having a savoury, almost salty minerality. It has naturally high acidity and a solid, structured body with moderate alcohol, giving it good ageing potential both as a still wine and as the backbone of long-aged Cava. Riper, warmer-site examples can show more stone fruit and a broader, oilier texture.",
