      "summary": "The most delicate and aromatic of the three classic Cava grapes, Parellada contributes finesse, floral lift and freshness to blends. It is generally the lightest-bodied and lowest-alcohol of the trio, often grown at higher altitudes to preserve elegance.",
      "viticulture": "Parellada buds and ripens later than Xarel-lo and Macabeo, so it performs best on higher-altitude, cooler sites in Penedès, since it is prone to losing aromatic delicacy and acidity if grown in hot, low-lying vineyards. It has moderate vigour and is relatively susceptible to drought stress, so it is often planted at elevation where diurnal temperature variation helps retain freshness. Its later budburst gives it some natural protection from spring frost, but this also means it needs a longer growing season to reach full ripeness.",
