      "winemaking": "Parellada is used almost exclusively in blends, most famously as the third component of the classic Cava blend with Macabeo and Xarel-lo, where it softens the blend and adds perfume. It is usually fermented in stainless steel at cool temperatures to preserve its delicate aromatics, without oak or extended skin contact. Malolactic conversion is typically avoided to protect its fresh, floral profile.",
