      "origin": "Austria/Central Europe (disputed, possibly Transylvania)",
      "summary": "An old, once-widely-planted Central European variety now most associated with Franken in Germany, where it produces dry, earthy, food-friendly whites, notably bottled in the traditional Bocksbeutel. It fell from favour through the 20th century as Müller-Thurgau expanded, but has seen a quality-driven revival among growers seeking a distinctive, terroir-expressive alternative to Riesling.",
      "viticulture": "Silvaner is a moderately vigorous, early-budding but relatively early-to-mid ripening variety that prefers deep, fertile soils and can be productive if not managed for quality; early budburst makes it susceptible to spring frost, and it can suffer from coulure in poor flowering conditions. It adapts well to a range of soils but shows particular affinity for Franken's limestone and shell-limestone (Muschelkalk) soils, where lower yields and old vines produce more mineral, concentrated wines. It is generally hardier than aromatic crossings like Müller-Thurgau, though it can still be vulnerable to botrytis in damp years.",
      "characteristics": "Silvaner typically shows a neutral-to-subtly aromatic profile with notes of green apple, pear, fresh herbs, white pepper and a characteristic earthy or mineral undertone; in warmer or riper examples it can develop broader stone-fruit and waxy notes. It generally has medium body, moderate-to-good acidity (lower than Riesling), and moderate alcohol, producing wines that are more about texture, weight and savoury character than high aromatic intensity. Old-vine, low-yield Franken examples can show impressive concentration, structure and ageing potential.",
      "winemaking": "Silvaner is almost always vinified as a dry, unoaked or neutral-oak still white, fermented cool in stainless steel to preserve freshness, though some premium examples see larger old oak or extended lees ageing (Sur Lie) for added texture. It is rarely blended, being valued for varietal, site-specific expression, particularly in Franken's Grosses Gewächs (GG) dry wines from top vineyard sites. Late-harvest and botrytis-affected sweet styles exist but are less common than for aromatic varieties.",
