      "origin": "Switzerland (bred by Hermann Müller)",
      "summary": "A German crossing bred in 1882 by Hermann Müller, a botanist from the Swiss canton of Thurgau, Müller-Thurgau became Germany's most planted grape for decades thanks to its reliability, early ripening and high yields. It produces soft, aromatic, low-acid wines, generally intended for early drinking.",
      "viticulture": "Müller-Thurgau buds early and ripens very early, reliably reaching adequate sugar levels even in cool, marginal climates, which made it hugely popular for guaranteeing a harvestable crop in poor German vintages. It is vigorous and high-yielding if not restricted, and combined with its early ripening and thin skins this makes it particularly prone to botrytis bunch rot and other fungal diseases in damp autumns; careful canopy management and yield control are needed for quality examples. It adapts to a wide range of soils and sites, which contributed to its rapid spread across Germany, Austria, Switzerland (as Rivaner) and northern Italy.",
      "characteristics": "Müller-Thurgau typically shows soft, low-to-medium acidity with gentle floral and lightly grapey-muscat-like aromas, along with notes of elderflower, peach and citrus blossom; it lacks the racy acidity and aromatic intensity of Riesling. Wines are usually light-to-medium bodied, low-to-moderate in alcohol, and made in an off-dry or medium-sweet style to balance the naturally soft acidity, though dry versions exist. Overall it produces easy-drinking, uncomplicated wines meant for youthful consumption rather than ageing.",
      "winemaking": "Almost always vinified as an unoaked, stainless-steel-fermented white, often with a touch of residual sugar (via süssreserve or halted fermentation) to balance its low acidity; malolactic conversion is generally avoided to prevent further acid loss. It is rarely oaked or given extended lees contact, and is mostly bottled as a varietal wine rather than blended, though it appears in basic Liebfraumilch-style blends. In Italy's Alto Adige it is made in a crisper, more mineral, higher-acid style than in Germany due to the cooler alpine sites used there.",
