      "origin": "Germany (bred by Georg Scheu)",
      "summary": "A German crossing bred in 1916 by Georg Scheu, Scheurebe is known for its pungent, exotic aromatics of blackcurrant, grapefruit and passion fruit. It produces wines ranging from crisp dry styles to intensely sweet botrytised dessert wines, particularly successful in the Pfalz and Rheinhessen.",
      "viticulture": "Scheurebe buds mid-to-late, helping it avoid spring frost, but ripens later than Müller-Thurgau and requires warm, sheltered sites to reach full ripeness; it is moderately vigorous with variable yields depending on clone and site. It is susceptible to poor flowering (coulure) in cool, wet springs and needs careful site selection to avoid this, but its relatively thick skins allow it to develop noble rot successfully for sweet wine production when conditions are right, while also offering decent resistance to unwanted rot in dry styles. It performs best on warmer, well-drained sites in Rheinhessen and Pfalz.",
      "characteristics": "Scheurebe is highly aromatic, with pronounced notes of blackcurrant leaf/cassis, grapefruit, passion fruit and other exotic tropical fruit, sometimes with a slightly pungent, almost catty or blackcurrant-bud character reminiscent of Sauvignon Blanc. It typically has high, racy acidity balanced against ripe fruit intensity, medium-to-full body, and can range from bone dry to lusciously sweet, with botrytised examples showing concentrated honeyed, marmalade richness alongside the varietal grapefruit character. Alcohol levels vary widely with style, from moderate in dry wines to more restrained in high-sugar dessert wines.",
      "winemaking": "Scheurebe is made across the full sweetness spectrum, from dry Trocken styles to Beerenauslese and Trockenbeerenauslese sweet wines affected by noble rot; it is essentially always unoaked, fermented and aged in stainless steel or neutral vessels to preserve its pungent varietal aromatics. Malolactic conversion is avoided to retain freshness. It is usually bottled as a single-varietal wine rather than blended, given its assertive, distinctive character.",
