      "summary": "A noble white grape of the northern and southern Rhône, Roussanne is prized for its perfumed, textured wines with notable ageing potential, though it is a notoriously difficult variety to grow. It is almost always blended with the more reliable Marsanne, to which it adds aromatic lift and acidity.",
      "viticulture": "Roussanne buds early and ripens late, making it vulnerable to spring frost and requiring a long, warm growing season to reach full ripeness; it is a low-yielding, vigorous but fragile variety, highly susceptible to powdery mildew, botrytis and various viral disorders, and it can suffer badly in windy or drought-stressed conditions. Its thin skins and tight bunches make it prone to rot, and it demands careful site selection, typically favouring well-drained, stony or limestone soils on warm, sheltered slopes. Because of these viticultural challenges it fell out of favour for a period before renewed interest in quality Rhône whites revived plantings.",
      "characteristics": "Roussanne produces perfumed, floral wines with notes of honeysuckle, apricot, pear, herbal tea and a distinctive waxy, honeyed character that deepens with age, sometimes developing notes reminiscent of camomile or beeswax. It typically has good natural acidity relative to Marsanne, medium-to-full body, and moderate-to-high alcohol, giving wines both aromatic finesse and structure capable of long bottle ageing, particularly in blends from top northern Rhône sites like Hermitage. On its own it can lack density, which is one reason blending with Marsanne is traditional.",
      "winemaking": "Roussanne is most commonly blended with Marsanne (and sometimes Viognier) in both northern Rhône whites (Hermitage Blanc, Crozes-Hermitage, St-Joseph) and southern Rhône blends (Châteauneuf-du-Pape Blanc); it is increasingly bottled as a single varietal in California and elsewhere. It is often barrel-fermented and aged in a mix of new and old oak, with lees stirring (bâtonnage) used to build texture, and malolactic conversion is common to soften acidity and add complexity. Both dry still and, occasionally, sweet late-harvest styles are made.",
