      "origin": "Charente region, southwest France",
      "summary": "A high-acid, neutral-to-lightly-aromatic grape historically used for distillation into Cognac and Armagnac, Colombard is now widely grown for fresh, fruity, easy-drinking dry white wines, particularly in South Africa and California. It buds and ripens relatively late and retains acidity well, making it valuable both for base wines for distillation and for crisp varietal whites.",
      "viticulture": "Colombard is a vigorous, productive variety that buds mid-season and ripens late, retaining good natural acidity even in warm climates, which is part of why it was historically prized as a base wine for Cognac and Armagnac distillation. It is susceptible to botrytis bunch rot and powdery mildew, particularly in humid conditions, and its high vigour requires canopy management to avoid excessive shading and dilution. It adapts well to a range of soils and climates, from the maritime Charente to the warm, dry conditions of South Africa's Western Cape and California's Central Valley.",
      "characteristics": "Colombard produces light, crisp, aromatically neutral-to-fruity wines with notes of green apple, grapefruit, and sometimes a light floral or grassy edge; in cooler or better sites it can show more pronounced citrus and tropical fruit character. It has notably high, refreshing acidity, light-to-medium body, and moderate alcohol, making it well suited to fresh, unoaked, early-drinking styles as well as to distillation, where its acid and neutral flavour profile are ideal for producing clean base wines.",
      "winemaking": "Colombard is used both for distillation into Cognac and Armagnac (fermented into a low-alcohol, high-acid base wine) and for still varietal or blended dry white wines, almost always vinified in stainless steel without oak or malolactic conversion to preserve freshness and acidity. It is frequently blended with more aromatic varieties such as Sauvignon Blanc or Chenin Blanc (as in South Africa) to add fruit character and freshness to inexpensive commercial blends. Cool fermentation and early bottling are typical to retain its fresh, fruity profile.",
