      "origin": "Southwest France (Charente/Gascony region)",
      "summary": "A historically important but now much-reduced variety, Folle Blanche was once the leading grape of Cognac and Armagnac distillation before phylloxera and its susceptibility to disease led to widespread replacement by Ugni Blanc. It survives today mainly in the Nantes region as Gros Plant du Pays Nantais and in a small revival in Armagnac.",
      "viticulture": "Folle Blanche buds early, making it highly vulnerable to spring frost, and is notoriously susceptible to fungal diseases, particularly downy mildew and grey rot, as well as to phylloxera (it is difficult to graft successfully), all of which contributed to its dramatic decline after the phylloxera epidemic of the late 19th century. It is a relatively vigorous, high-yielding variety when healthy, producing thin-skinned, tightly packed bunches that are prone to rot in damp conditions. It requires careful site selection and vine management to be viable commercially today.",
      "characteristics": "Folle Blanche produces very high-acid, light-bodied, neutral-to-lightly-aromatic wines with notes of green apple, citrus, and a distinct sharp, tart edge; it rarely shows much aromatic complexity, which suited its historic role as a base wine for distillation rather than fine still wine. In still wine form (as Gros Plant) it is typically bone dry, thin, and searingly crisp, often bottled sur lie to add a little textural roundness to counter its austerity.",
      "winemaking": "Historically vinified as a base wine for distillation into Cognac and Armagnac, where its high acidity and low alcohol were ideal for producing clean, ageable eaux-de-vie; today it is mostly made into simple, very dry, high-acid still white wine, particularly Gros Plant du Pays Nantais near Muscadet country, often aged briefly sur lie for added texture. It is essentially never oaked and rarely blended in its still-wine form, though it appears in some Armagnac blends alongside Ugni Blanc and Colombard.",
