      "origin": "Burgundy, France (now centred in Pays Nantais)",
      "summary": "Despite its Burgundian origins, Melon de Bourgogne is today almost exclusively associated with Muscadet, the crisp, dry, often sur lie-aged white of the Pays Nantais at the mouth of the Loire. It was planted here in large quantities after the severe winter of 1709 and again post-phylloxera due to its cold-hardiness and early ripening.",
      "viticulture": "Melon de Bourgogne buds and ripens early, and it is notably cold-hardy and frost-resistant relative to many varieties, which is part of why it became established in the cool, maritime climate of the Pays Nantais. It is a relatively vigorous, productive variety, susceptible to powdery and downy mildew as well as botrytis in humid coastal conditions, requiring diligent canopy management. It is well suited to the varied soils of Muscadet, including gneiss, granite, gabbro and schist, and its neutral character means terroir differences show through relatively clearly.",
      "characteristics": "Melon de Bourgogne is a relatively neutral grape, producing light-bodied, high-acid, dry white wines with subtle notes of green apple, citrus, white flowers, and, particularly with sur lie ageing, a distinctive bready, yeasty, sometimes faintly saline or briny character. Alcohol levels are typically modest, and the wine's appeal lies in its freshness, crisp acidity and textural interest from lees contact rather than aromatic intensity. Higher-quality, terroir-driven Muscadet from top crus can show more depth, saline minerality and ageing potential than basic examples.",
      "winemaking": "The defining winemaking technique for Melon de Bourgogne is elevage sur lie: the wine is kept on its fine lees, often without racking, through the winter following harvest and bottled directly off the lees (typically in spring), which adds a light textural creaminess, a slight spritz, and bready, autolytic notes. It is almost always fermented and aged in stainless steel or neutral vessels without oak, and malolactic conversion is generally encouraged to soften its naturally high acidity, though top cru wines are increasingly made with more restrained, terroir-focused approaches and sometimes longer lees ageing.",
