      "origin": "Germany (bred in Württemberg)",
      "summary": "A German crossing of Riesling and the red grape Trollinger, bred in 1929, Kerner was developed to combine Riesling-like aromatics with easier ripening and greater frost resistance. It became widely planted in Germany from the 1970s onward and is also notably grown in England and South Tyrol.",
      "viticulture": "Kerner buds later than many varieties (a useful trait inherited to help avoid spring frost, one of the original breeding goals) but ripens relatively early and reliably, even in cooler, marginal sites, which made it attractive for expanding plantings into less favourable German vineyard sites. It is a vigorous, productive variety, moderately susceptible to downy and powdery mildew, and its productivity needs to be managed through yield restriction to achieve concentration and quality comparable to good Riesling. It performs well across a range of soils and is valued for its reliability in cooler climates such as England.",
      "characteristics": "Kerner produces aromatic wines reminiscent of Riesling, with notes of green apple, citrus, peach and floral blossom, generally slightly softer and less racy in acidity than true Riesling but still fresher than Müller-Thurgau. It has medium body, good-to-high acidity, and can be made in styles ranging from dry to medium-sweet, with moderate alcohol typical. While it can offer real quality, it generally lacks the precision, minerality and ageing potential of top Riesling.",
      "winemaking": "Kerner is almost always made as an unoaked, stainless-steel-fermented varietal white, often finished off-dry or medium-sweet with a touch of residual sugar to balance its acidity, in a style similar to everyday German Riesling or Müller-Thurgau. Malolactic conversion is typically avoided to preserve freshness, and it is rarely blended, given its status as a Riesling-alternative varietal wine. In England it has been used both for still wines and as a component in sparkling wine production, valued for its reliable ripening.",
