      "summary": "A German crossing developed in the 1930s, Bacchus is a highly aromatic variety valued for producing fragrant, fruity, easy-drinking wines and as a valuable blending component. It has found notable success in England, where its reliable ripening and pronounced aromatics have made it something of a signature grape for English still wine.",
      "viticulture": "Bacchus buds relatively early and ripens early, making it well suited to cooler, marginal climates where later-ripening aromatic varieties would struggle, though early budding leaves it somewhat exposed to spring frost. It is a moderately vigorous variety, susceptible to botrytis bunch rot given its tendency toward tight bunches, and yields need to be managed to avoid dilution of its aromatic intensity. Its reliable ripening in cool climates has driven its rapid expansion in England over the past two decades.",
      "characteristics": "Bacchus is highly aromatic, with pronounced notes of elderflower, blackcurrant leaf, grapefruit and a herbaceous, sometimes almost Sauvignon Blanc-like green character, along with floral and green apple notes. It typically has good-to-high acidity, light-to-medium body, and moderate alcohol, and is generally made in a dry-to-off-dry style designed to showcase its intense, upfront aromatics rather than structure or ageing potential. It is often compared informally to Sauvignon Blanc for its pungency, though the flavour profile is distinct.",
      "winemaking": "Bacchus is typically vinified as an unoaked, cool-fermented, stainless-steel varietal white to preserve its pronounced aromatics, and is usually made in a dry or off-dry style meant for early drinking. Malolactic conversion is avoided, and it is sometimes blended with other aromatic varieties (such as Reichensteiner, Schönburger, or Ortega in England) to build a fuller wine, though top examples are increasingly bottled as a single varietal to showcase its character. It is not typically used for sparkling wine production, unlike some other cool-climate German crossings.",
