      "origin": "Switzerland/Lake Geneva region (disputed)",
      "summary": "An ancient, historically significant but naturally low-aromatic variety, Chasselas is the signature white grape of Switzerland, particularly the Vaud region around Lake Geneva, where it is known as Fendant. It is also grown as a table grape in many countries, reflecting its dual-purpose history.",
      "viticulture": "Chasselas is an early-budding, early-ripening variety, moderately vigorous and productive, well suited to a range of climates from the cool alpine sites of Switzerland to warmer regions like Alsace and southern Germany. It has relatively limited natural resistance to powdery mildew and can be prone to overcropping if not managed, which further dilutes its already subtle flavour profile; careful site selection and yield control are important for quality. It is highly terroir-transparent, meaning site and soil differences, such as Vaud's steep, terraced vineyards above Lake Geneva, show through clearly in the finished wine.",
      "characteristics": "Chasselas is a naturally neutral, subtly flavoured grape, showing delicate notes of green apple, white flowers, a light nuttiness and, in the best examples, a distinctive mineral or saline character derived strongly from its site. It has relatively low-to-moderate acidity and light-to-medium body, with moderate alcohol, making it a wine that relies on texture, subtlety and terroir expression rather than aromatic intensity or high acid structure. Because of its neutrality, quality strongly depends on vineyard site, old vines and low yields.",
      "winemaking": "Chasselas is almost always vinified as a dry, unoaked still white, fermented in stainless steel or neutral vessels, with lees contact/ageing (sur lie) sometimes used in Switzerland to add texture and complexity to its naturally subtle profile. Malolactic conversion is used in some regions to soften acidity further. It is rarely blended, being valued as a single-varietal expression of specific vineyard sites, particularly in Switzerland's Vaud region where individual crus (e.g. Dézaley, Calamin) are prized.",
