      "summary": "Arneis is an aromatic white grape native to the Roero hills of Piedmont, historically overshadowed by the region's red varieties but revived as a fashionable dry white from the 1970s onward. It produces soft, perfumed, medium-bodied wines with peach and almond notes, and is Piedmont's most important native white grape.",
      "viticulture": "Arneis buds early and is prone to spring frost damage, then ripens in a mid-season window that requires careful monitoring since it loses acidity quickly once fully ripe. It is a vigorous variety that needs canopy management and yield control to avoid diluted, neutral wines, and it is notably susceptible to powdery mildew and to bunch rot in damp years given its fairly tight-ish, thin-skinned berries. It performs best on the sandy, calcareous marl soils of the Roero hills, which give freshness and finesse, and it prefers well-ventilated, south-facing sites to ensure even ripening.",
