      "winemaking": "The vast majority of Arneis is vinified as a dry, unoaked or lightly oaked white, fermented in stainless steel to preserve its delicate aromatics, though some premium examples see partial barrel fermentation or a portion of lees ageing for texture. Malolactic conversion is generally avoided or only partially used to retain freshness, given the grape's naturally moderate acid. Historically it was interplanted with Nebbiolo in the Roero and Barolo/Barbaresco zones and picked early to be co-fermented with the red grapes, softening Nebbiolo's tannin and adding perfume; today it is almost always vinified as a varietal white. A small amount is also made in a late-harvest or passito style.",
