      "summary": "Ribolla Gialla is an old, high-acid white grape of the Friuli and Collio hills, straddling the Italian-Slovenian border where it is also known as Rebula. It has become closely associated both with crisp modern dry whites and with the extended skin-contact 'orange wine' movement pioneered by growers in Friuli's Collio and Slovenia's Brda.",
      "viticulture": "Ribolla Gialla is a late-budding, late-ripening variety with naturally high, reliable acidity and thick skins, which gives it good resistance to botrytis bunch rot and makes it well suited to extended maceration. It is moderately vigorous and can be a generous producer if not restricted, though quality growers keep yields in check to concentrate flavour. It thrives on the marl-and-sandstone (ponca/flysch) hillside soils of the Collio and Colli Orientali, which contribute minerality and structure, and it favours well-drained, sunny slopes to reach full ripeness given its late cycle.",
      "characteristics": "In its fresh, unoaked form Ribolla Gialla shows green apple, citrus, white flowers, and a saline, mineral edge, with searingly high acidity and a light-to-medium body. When made with extended skin contact it turns amber-orange in colour and develops notes of dried apricot, tea leaf, orange peel, honey, and a grippy tannic texture that is unusual for a white grape. Alcohol levels are typically moderate, and even in warmer vintages the grape retains a backbone of acidity that keeps both styles taut rather than heavy.",
      "winemaking": "Two distinct winemaking traditions exist side by side: a modern, stainless-steel, low-intervention approach producing crisp, aromatic dry whites, and a naturalist, amphora-or-large-oak-aged approach using weeks to months of skin contact, native yeast fermentation, and minimal sulphur, associated with pioneers such as Josko Gravner and Stanko Radikon. Malolactic conversion is usually avoided to preserve the grape's signature acidity. It is used both as a single-varietal wine and, less commonly, blended with other Friulian whites such as Friulano or Malvasia Istriana. It is also a component in some sparkling wines in Friuli and Slovenia.",
