      "origin": "Friuli-Venezia Giulia, northeast Italy",
      "summary": "Friulano is the signature white grape of Friuli's Collio and Colli Orientali hills, producing dry, medium-bodied wines with a distinctive note of green almond. It was long sold as 'Tocai Friulano' until an EU ruling forced a name change in 2007, and DNA profiling later revealed it is genetically identical to Chile's Sauvignonasse rather than related to Sauvignon Blanc or Hungarian Tokaji grapes.",
      "viticulture": "Friulano buds and ripens in a mid-season window, is moderately vigorous, and generally gives reliable, generous yields if not restrained through pruning. It is susceptible to powdery mildew and can suffer from poor fruit set (coulure) in cool, wet flowering periods, and its relatively loose bunches offer some natural resistance to botrytis. It performs best on the same marl-sandstone (ponca) hillside soils that suit Ribolla Gialla and Sauvignon Blanc in the Collio and Colli Orientali, where good drainage and sun exposure help it reach full phenolic ripeness.",
