      "winemaking": "Friulano is almost always made as a dry, still, varietal white, typically fermented and aged in stainless steel or neutral large oak (botti) to preserve its textural, savoury character rather than adding overt oak spice. Some producers use extended lees contact (sur lie ageing) with occasional bâtonnage to build texture and complexity, and malolactic conversion is used selectively depending on house style and vintage acidity. It is occasionally blended with Ribolla Gialla, Malvasia Istriana, or Sauvignon Blanc in Friulian white blends, but the finest examples from Collio and Colli Orientali are single-varietal.",
