      "summary": "Grillo is a Sicilian white grape historically prized as the backbone of Marsala fortified wine, now increasingly bottled as a fresh, aromatic dry varietal white. DNA analysis confirms it is a natural crossing of Catarratto and Muscat of Alexandria (Zibibbo), which explains its combination of structure and lifted aromatics.",
      "viticulture": "Grillo is a late-budding, fairly late-ripening variety well suited to Sicily's hot, dry, Mediterranean climate, and it retains good natural acidity even in high heat, which is prized for Marsala production. It is a vigorous, drought-tolerant vine that performs well on the island's calcareous and clay soils, particularly around Marsala in the west, and it can be trained in bush-vine (alberello) form to cope with wind and heat stress. It is moderately susceptible to powdery mildew but generally robust against fungal disease thanks to Sicily's dry growing season, and yields need to be controlled for quality dry-wine production versus the higher yields historically tolerated for fortified wine.",
      "characteristics": "Modern dry Grillo shows citrus, white peach, herbal and Mediterranean scrub (garrigue) notes, sometimes with a faint fennel or aniseed lift inherited from its Muscat parentage, backed by notably good acidity for a warm-climate grape. Body is medium, alcohol tends to be moderate-to-high given Sicily's warmth, and the best examples balance ripe fruit with a saline, textured finish. In its historical role for Marsala, it was valued for oxidative stability and the ability to retain freshness even after fortification and ageing.",
