      "viticulture": "Catarratto is a vigorous, productive variety that buds mid-season and ripens relatively late, and it is naturally prone to very high yields, which historically made it a workhorse grape for bulk production and required deliberate restriction for quality wine. It is well adapted to Sicily's hot, dry summers and shows good drought tolerance, though it can be susceptible to powdery mildew in damper years. It is grown across a range of Sicilian soils but performs particularly well on the calcareous, clay-limestone soils of western Sicily around Trapani and Alcamo, and low-yield, hillside plantings produce noticeably more concentrated fruit than valley-floor vines.",
