      "viticulture": "Inzolia is a moderately vigorous variety that buds early and ripens in a mid-to-late window, and it is notably susceptible to powdery mildew, which requires vigilant canopy management in humid sites. It prefers hot, dry, well-ventilated conditions and performs best on well-drained soils, whether the sandy coastal plots of western Sicily or the granitic soils of Elba and coastal Tuscany where it is grown as Ansonica; it can struggle with poor fruit set in unfavourable flowering weather. Yields need to be kept moderate to preserve its delicate aromatics, since overcropping quickly dilutes its character.",
