      "origin": "Madeira, Portugal",
      "summary": "Sercial is the driest and most acid-driven of Madeira's four classic noble grapes, traditionally planted on the island's highest, coolest sites. Its fortified wines are bone-dry, searingly high in acid, and built for long ageing, making it the benchmark grape for the driest style on Madeira's sweetness scale.",
      "viticulture": "Sercial is a late-budding, very late-ripening variety, one of the latest to ripen among Madeira's classic grapes, which is why it is traditionally planted at the island's highest, coolest elevations where it can achieve a long, slow ripening season. It is a low-yielding, relatively vigour-modest vine that struggles to ripen fully in cooler years, and it was historically devastated, like most of Madeira's vineyards, by phylloxera and powdery mildew in the 19th century, prompting widespread replanting on hybrid or grafted rootstock. It favours Madeira's volcanic, well-drained soils and the terraced (poios) vineyards that allow cultivation on the island's steep slopes.",
      "characteristics": "Sercial produces wines with pronounced, searing acidity, a lean, light-to-medium body, and aromas of green almond, citrus peel, and a saline, briny tang, with the least residual sweetness of the four noble Madeira grapes. Even after fortification and the island's characteristic oxidative, heat-influenced ageing (estufagem or canteiro), the wine retains a bracing, almost austere dryness balanced by the sweetness-suggesting concentration typical of great Madeira. With extended cask ageing it develops notes of dried citrus, roasted nuts, and a pungent, tangy finish that remains remarkably fresh even in decades-old examples.",
      "winemaking": "Sercial is fortified with grape spirit during fermentation, but at a later stage than the sweeter Madeira styles, so more of the grape's natural sugar converts to alcohol before fortification, resulting in the driest style on the classic Madeira sweetness scale (Sercial, Verdelho, Bual, Malmsey, from dry to sweet). The wine is then aged oxidatively, either in the slow, traditional canteiro method (ambient warmth over years) or the faster estufagem tank-heating method for basic wines, developing Madeira's signature caramelised, nutty, volatile character. It is typically bottled as an aged, often vintage-dated or colheita, fortified wine rather than a table wine, and its high acidity gives it exceptional longevity, with well-known examples surviving a century or more.",
