      "origin": "Madeira, Portugal",
      "summary": "Verdelho is the second-driest of Madeira's four noble grapes, producing medium-dry fortified wines with smoky, honeyed complexity, and it is also grown as a table-wine grape in Australia, where it has developed its own distinct, fresh varietal identity. On Madeira it occupies the middle ground on the island's dry-to-sweet grape scale, between the austere Sercial and the richer Bual.",
      "viticulture": "Verdelho buds and ripens earlier than Sercial but later than Bual, giving it a mid-position on Madeira's altitude-planting hierarchy, typically grown at mid-elevation sites on the island's volcanic terraces. It is a moderately vigorous, reasonably productive vine, more tolerant of a range of sites than Sercial, and it is grown on trellised or pergola systems in Madeira's traditional poios terraces to maximise sun exposure on steep slopes. In Australia, particularly historically in the Hunter Valley, it proved well suited to warm, humid conditions, being relatively disease-tolerant and able to retain acceptable acidity even in a hot climate, though it is prone to powdery mildew.",
      "characteristics": "Madeira Verdelho shows a medium-dry profile with notes of dried apricot, smoke, orange peel, and a faintly nutty, honeyed character, supported by high acidity that keeps the wine from feeling cloying despite its greater sweetness relative to Sercial. As a dry Australian table wine, Verdelho instead shows fresh, tropical-leaning citrus and stone-fruit character with crisp acidity and light-to-medium body, a very different expression from its fortified Madeira role. Alcohol in the fortified Madeira style is elevated due to the addition of grape spirit, while the Australian dry table-wine style stays at conventional table-wine strength.",
      "winemaking": "In Madeira, Verdelho is fortified partway through fermentation at a point leaving a moderate level of residual sugar, placing it in the medium-dry category on the classic sweetness scale, then aged oxidatively via canteiro or estufagem to develop Madeira's characteristic baked, tangy complexity. In Australia, by contrast, Verdelho is made as an unfortified, usually unoaked or lightly oaked dry white table wine, fermented cool in stainless steel to preserve its fresh citrus and tropical fruit character. The grape is not typically used for extended lees ageing or heavy oak in either tradition, with Madeira's ageing character instead coming from oxidative cask ageing and heat rather than new oak.",
      "keyRegions": [
        "Madeira, Portugal",
        "Hunter Valley, New South Wales, Australia",
        "Douro Valley, Portugal (as Gouveio)"
      ],
      "notableStyles": [
        {
          "name": "Madeira Verdelho (medium-dry/meio seco)",
          "notes": "The second-driest classification on the island's sweetness scale, smoky and tangy with balancing acidity."
        },
        {
          "name": "Australian dry varietal Verdelho",
          "notes": "A completely different, unfortified style: fresh, citrusy, and easy-drinking, especially associated with the Hunter Valley and Western Australia."
        }
      ],
      "notes": [
        "Verdelho is genetically linked to Gouveio, a white grape grown in Portugal's Douro Valley, illustrating the historical exchange of vine material between mainland Portugal and Madeira.",
        "Australia's dry table-wine Verdelho tradition developed almost entirely independently of Madeira's fortified use of the grape, giving the same variety two very different global identities.",
        "It sits second on Madeira's four-step dry-to-sweet grape hierarchy: Sercial, Verdelho, Bual, Malmsey.",
        "Verdelho was one of the grapes carried by Portuguese sailors to various colonial-era ports of call, contributing to its historic association with maritime trade routes."
      ]
