        "It did not become widely planted in Bordeaux until after the mid-18th century, later than Cabernet Franc or Malbec.",
        "Its thick skin and resistance to rot made it a favourite for replanting after the phylloxera epidemic.",
        "Green bell pepper aroma comes from methoxypyrazine compounds, which decrease as grapes reach full ripeness and increase in under-ripe or cool-climate fruit."
