      "origin": "Northern Rhône Valley, France",
      "summary": "Syrah, known as Shiraz in Australia and South Africa, produces some of the world's most powerful and age-worthy red wines, ranging from the peppery, elegant reds of the Northern Rhône to the rich, jammy Shiraz of the Barossa Valley. DNA analysis has shown it to be a natural crossing of two obscure varieties from southeastern France, dispelling older legends of a Middle Eastern or Persian origin. It is prized for its deep colour, full body, and distinctive peppery spice character.",
      "viticulture": "Syrah buds relatively late, giving it some protection from spring frost, but it needs a long, warm growing season to ripen fully, performing best in warm climates while still capable of elegance in moderate ones such as the Northern Rhône's steep slopes. The vine is vigorous and susceptible to downy mildew in humid conditions, and can suffer from bunch stem necrosis, though it is generally hardy and adaptable to a range of soils, including the granite of Hermitage and Côte-Rôtie and the sandy, old-vine soils of Barossa. Careful canopy management is needed to avoid excessive vigour shading the fruit, which would otherwise increase green, herbaceous character at the expense of ripe fruit and pepper notes.",
      "characteristics": "In cooler expressions such as the Northern Rhône, Syrah shows black pepper, violet, blackberry, and smoked meat or bacon fat aromas with firm tannins and pronounced acidity; in warm-climate Shiraz from regions like Barossa, the profile shifts toward riper blackberry jam, chocolate, licorice, and dried herbs with softer tannins and higher alcohol. It is consistently full-bodied with deep, almost opaque colour, high tannin, and medium to high acidity, and typically has strong ageing potential, developing leather, game, and earthy complexity with time in bottle.",
      "winemaking": "Extended maceration is common to extract Syrah's abundant colour and tannin, and oak ageing, in French oak in the Rhône and often American oak in parts of Australia, is typical, contributing vanilla, coconut, and spice notes. In the Northern Rhône it is traditionally co-fermented with a small proportion of the white grape Viognier in appellations like Côte-Rôtie, which softens colour slightly and adds floral lift, while in the Southern Rhône and Australia it is frequently blended with Grenache and Mourvèdre (the GSM blend). Styles range from the structured, savoury wines of Hermitage to the opulent, high-alcohol Shiraz of the Barossa Valley.",
