      "origin": "Aragón, northern Spain",
      "summary": "Grenache, called Garnacha in its native Spain, is one of the most widely planted red grapes in the world and a key component of many of the Mediterranean's great blended reds, from Châteauneuf-du-Pape to Priorat. It is valued for its high sugar accumulation, generous alcohol, and soft, juicy fruit character, and it thrives in hot, dry, windy conditions where many other varieties struggle. It is most often blended, though old-vine, single-varietal examples can show remarkable depth and concentration.",
      "viticulture": "Grenache buds late, offering good protection against spring frost, but needs a long, hot growing season to ripen fully and is often one of the last varieties harvested in a region. It is naturally vigorous and drought-resistant, well suited to arid, low-fertility soils and windy sites, and is traditionally trained as low-lying bush vines (gobelet) without irrigation in regions like Priorat and Châteauneuf-du-Pape. Its main viticultural weaknesses are a strong susceptibility to coulure during flowering, which can drastically reduce yields, and its thin skin, which combined with high sugar levels makes it prone to oxidation both on the vine and in the winery.",
      "characteristics": "Grenache typically produces pale-to-medium coloured wines with red berry fruit such as strawberry and raspberry, white pepper, and dried herb notes, often with a notable warmth and sweetness of fruit. It is medium to full-bodied with naturally high alcohol due to its sugar-accumulating tendency, low to medium tannin, and low to medium acidity, which can leave poorly made examples feeling flabby or overly alcoholic if not balanced by blending partners or careful site selection. Old-vine examples can show great concentration, spice, and garrigue-like herbal complexity.",
      "winemaking": "Because of its naturally soft tannins and tendency toward oxidation, gentler extraction and protective handling are common, and it is very frequently blended with more tannic or acidic varieties such as Syrah, Mourvèdre, or Carignan to add structure and colour. Oak ageing varies widely by style, from unoaked or lightly oaked fresh reds and rosés to barrel-aged examples in premium regions like Priorat. It is also used to make fortified sweet wines (Vin Doux Naturel) in Roussillon, such as Banyuls and Maury, showcasing its high sugar potential.",
