      "origin": "Tuscany, central Italy",
      "summary": "Sangiovese is Italy's most widely planted red grape and the backbone of Tuscany's most famous wines, including Chianti, Brunello di Montalcino, and Vino Nobile di Montepulciano. Its name is popularly linked to 'sanguis Jovis', the blood of Jupiter, reflecting its long history in central Italy. It is known for high acidity and firm tannin, giving savoury, food-friendly wines that range from light and juicy to powerful and age-worthy depending on clone, site, and winemaking.",
      "viticulture": "Sangiovese buds early but ripens late, requiring a long growing season and good sun exposure, which is why the best sites in Tuscany are typically well-exposed hillside vineyards. It is a genetically diverse variety with numerous clones of varying quality, ranging from higher-yielding, lesser clones to the superior, lower-yielding Sangiovese Grosso selections used for Brunello. The thin skins and tight bunches make it susceptible to downy mildew and rot in wet conditions, and it is sensitive to site, often showing markedly different character even across neighbouring vineyards, making clonal selection and vineyard siting critical to quality.",
      "characteristics": "Sangiovese typically shows sour red cherry, red plum, and dried herb aromas, often with a distinctive savoury, earthy, tomato leaf, or dried oregano character, and floral violet notes in higher-quality examples. It is medium to full-bodied with notably high acidity and firm, sometimes rustic tannin, moderate alcohol, and a garnet-tinged colour that lightens with age. With oak ageing and bottle maturation it develops leather, dried fig, balsamic, and tobacco complexity, particularly in Brunello di Montalcino.",
      "winemaking": "Traditional Sangiovese winemaking involves maceration to extract its naturally firm tannins, historically in large old Slavonian oak casks (botti), though many modern producers use smaller French barriques for a softer, more international style. It is often blended, most famously with small proportions of other varieties in Chianti (historically including white grapes, now more often Cabernet Sauvignon, Merlot, or native reds like Canaiolo), though Brunello di Montalcino must be 100% Sangiovese. Styles range from everyday, fruity Chianti to serious, structured, long-ageing Brunello and modern 'Super Tuscan' blends with international varieties.",
