      "origin": "Piedmont, northwest Italy",
      "summary": "Nebbiolo is the grape behind Barolo and Barbaresco, widely regarded as Italy's greatest and most age-worthy red wines. Despite its relatively pale colour, it produces wines of exceptional structure, with high tannin and high acidity that allow decades of ageing. Its name is thought to derive from 'nebbia', the Italian word for fog, which blankets the Langhe hills during the grape's characteristically late harvest.",
      "viticulture": "Nebbiolo buds early, making it vulnerable to spring frost, yet ripens very late, often the last variety harvested in Piedmont, and it demands the best, warmest, south-facing hillside sites to ripen fully. It is a vigorous vine sensitive to site and soil, performing best on calcareous marl soils, and it is susceptible to downy mildew and, given its thin skin, to bunch rot in wet autumns. Its very particular site requirements mean that only a small number of well-exposed vineyards in Piedmont, and pockets elsewhere such as Valtellina in Lombardy, can ripen it to full quality.",
      "characteristics": "Nebbiolo produces relatively pale, garnet-rimmed wines that belie their power, with aromas of rose, cherry, tar, dried herbs, licorice, and, with age, truffle and leather. It is full-bodied with very high tannin and very high acidity despite the pale colour, and moderate to high alcohol, making it a variety that typically needs significant bottle age to soften and reveal its full complexity. Young Nebbiolo can be austere and tannic, while well-aged examples are prized for their perfumed complexity and silky, resolved tannin.",
      "winemaking": "Traditional Nebbiolo winemaking involves long maceration periods to manage its high tannin, historically followed by extended ageing in large old Slavonian oak botti, though since the 1980s many producers have adopted shorter macerations and smaller French barriques for a more approachable, fruit-forward style, a shift often referred to as the 'Barolo Wars'. It is rarely blended, as Barolo and Barbaresco DOCG regulations require 100% Nebbiolo, though simpler wines like Langhe Nebbiolo offer an earlier-drinking varietal expression. Styles range from powerful, decades-worthy Barolo to lighter, more approachable Nebbiolo d'Alba.",
