      "origin": "Northern Spain",
      "summary": "Tempranillo is Spain's most important native red grape and the foundation of its two most prestigious red wine regions, Rioja and Ribera del Duero. Its name derives from 'temprano', the Spanish word for early, reflecting its relatively early ripening compared to many other Spanish varieties. It is known for producing wines with a distinctive balance of red and black fruit, moderate acidity, and an affinity for oak ageing that has shaped Spain's traditional Crianza-Reserva-Gran Reserva classification system.",
      "viticulture": "Tempranillo buds relatively early and ripens early to mid-season, which allows it to succeed in the relatively continental, high-altitude climates of northern and central Spain where it can retain acidity despite the heat. It has moderately thick skins offering reasonable resistance to disease, though it can be susceptible to drought stress, powdery mildew, and viral diseases such as leafroll virus, and it generally prefers well-drained, poor soils that limit vigour. Yields must be controlled for quality, as the variety can be prone to overproduction, diluting flavour if not managed through pruning and site selection.",
      "characteristics": "Tempranillo typically shows red plum, strawberry, and cherry fruit with savoury, tobacco, leather, and dill or vanilla notes that intensify with oak ageing. It is medium to full-bodied with medium tannin, medium acidity, and moderate alcohol, giving wines that balance freshness with structure, and it develops attractive dried fruit, spice, and leather complexity with extended ageing, particularly in the American oak traditionally used in Rioja.",
      "winemaking": "Extended oak ageing, historically in American oak barrels, is central to Tempranillo's classic style, giving rise to Spain's traditional ageing categories (Crianza, Reserva, Gran Reserva) that specify minimum time in barrel and bottle before release. It is frequently blended with Garnacha, Graciano, and Mazuelo in Rioja for added aromatics and structure, while in Ribera del Duero it is often bottled with a smaller proportion of blending partners or as a varietal wine. In Portugal's Douro Valley, where it is called Tinta Roriz or Aragonez, it is a key component of both table wine and Port blends.",
