      "origin": "Cahors, southwest France",
      "summary": "Malbec is a grape of French origin that has become most closely associated with Argentina, where it produces the country's signature red wine, especially in the high-altitude vineyards of Mendoza. In its historic home of Cahors, it makes deeply coloured, tannic wines sometimes nicknamed 'black wine'. The grape offers deep colour, ripe dark fruit, and, particularly in Argentina, notably soft and approachable tannins.",
      "viticulture": "Malbec buds and ripens in the mid-season, and while historically prone to coulure, poor fruit set, and susceptibility to frost, disease, and rot in the cooler, damper climate of southwest France, it thrives in the warm, dry, high-altitude conditions of Mendoza, where these issues are far less pronounced. Argentina's high-altitude vineyards, often over 900 metres, provide intense sunlight balanced by cool nights, which helps the grape retain acidity and aromatic freshness while achieving full ripeness and thicker skins than in its French homeland. In Cahors, it requires careful site selection on limestone plateaus or terraces to ripen reliably.",
      "characteristics": "Malbec produces deeply coloured, almost inky wines with plum, blackberry, and violet aromas, often taking on chocolate, mocha, and vanilla notes with oak ageing. Argentine Malbec is typically medium to full-bodied with soft, velvety tannins, moderate to high alcohol, and ripe, generous fruit, while Cahors Malbec tends to be more rustic, tannic, and earthy, with higher acidity and firmer structure reflecting its cooler origin and traditional winemaking.",
      "winemaking": "In Argentina, Malbec is often made as a varietal wine with moderate to significant new oak ageing, in French or sometimes American barrels, to add sweet spice and vanilla notes that complement its ripe fruit. In Cahors, French law requires a minimum proportion of Malbec (locally called Côt or Auxerrois) in the blend, often complemented by Merlot and Tannat, and traditional winemaking there produces darker, more tannic, food-oriented wines. It is also grown in Chile and, to a lesser extent, elsewhere in the New World, generally used for deeply coloured varietal or blended wines.",
