      "origin": "Bordeaux and the Loire Valley, France",
      "summary": "Cabernet Franc is a versatile red grape best known as a blending component in Bordeaux and as a distinguished varietal wine in the Loire Valley. It is a parent, through natural crossings, of both Cabernet Sauvignon and Merlot, giving it a foundational role in the history of Bordeaux's great red varieties. It typically produces lighter, more aromatic, and more herbaceous wines than Cabernet Sauvignon, with pronounced red fruit and floral character.",
      "viticulture": "Cabernet Franc buds and ripens earlier than Cabernet Sauvignon, making it better suited to cooler sites and more marginal climates such as the Loire Valley, though this earlier budding does increase its exposure to spring frost. It is generally more cold-hardy and less vigorous than Cabernet Sauvignon, and its thinner skins make it somewhat more susceptible to botrytis and other fungal diseases in humid conditions. It adapts well to a range of soils but shows particularly distinctive character on the tuffeau limestone and gravel soils of the Loire and the sandy/gravel soils of Bordeaux's Right Bank.",
      "characteristics": "Cabernet Franc typically shows red fruit such as raspberry and redcurrant alongside characteristic green, herbaceous notes of bell pepper, leafy stem, and graphite or pencil shavings, along with a distinctive violet floral aroma. It is medium-bodied with medium to high tannin, high acidity, and generally lower alcohol than Cabernet Sauvignon, giving lighter, more elegant, fresher wines, though warmer sites and riper vintages can yield fuller, riper expressions with softer green notes.",
      "winemaking": "In the Loire Valley it is typically made as a varietal wine, ranging from unoaked, fresh, fruit-driven styles to more structured, oak-aged examples capable of ageing. In Bordeaux it is used primarily as a blending component with Merlot and Cabernet Sauvignon, adding aromatic lift, freshness, and structure, most famously forming the majority of the blend in some top St-Émilion estates. Oak ageing, when used, is generally French oak and applied judiciously to avoid overwhelming its delicate aromatics.",
