      "origin": "Bordeaux, France (historic)",
      "summary": "Carménère was one of the original six red grapes of Bordeaux before nearly disappearing after the phylloxera epidemic of the late 19th century, only to be rediscovered thriving under a different identity in Chile more than a century later. For decades Chilean growers believed their Carménère vines were Merlot, until ampelographer Jean-Michel Boursiquot correctly identified the variety in 1994. It has since become Chile's signature grape, prized for its distinctive smoky, herbal character and soft tannins.",
      "viticulture": "Carménère buds relatively early but ripens very late, requiring a long, warm growing season to fully mature; in cooler or shorter seasons it retains pronounced green, herbaceous, vegetal notes from unripe pyrazines. It is notably susceptible to coulure and poor fruit set, which was a significant factor in its decline in Bordeaux's cooler, wetter climate after phylloxera forced growers to replant with more reliable varieties. Chile's warm, dry, sunny Central Valley climate, particularly areas like Rapel and Colchagua, provides the extended ripening window the variety needs to reach full maturity and shed excessive green character.",
      "characteristics": "When fully ripe, Carménère shows dark fruit such as blackberry and black cherry, along with distinctive notes of green bell pepper, soy sauce, smoke, and dark chocolate or mocha; underripe examples can show excessive, unpleasant green, vegetal character. It is medium to full-bodied with soft, moderate tannins, moderate acidity, and moderate to high alcohol when properly ripened, giving smooth, approachable wines quite different in texture from the firmer tannins of Cabernet Sauvignon.",
      "winemaking": "Achieving full phenolic ripeness through careful vineyard site selection and picking decisions is the central winemaking challenge for Carménère, since underripe fruit brings unwanted green character. It is made both as a varietal wine and blended with Cabernet Sauvignon, Merlot, or Syrah to add colour, softness, and distinctive spice, and oak ageing, typically French oak, is common for premium bottlings, adding sweet spice that complements its natural smoky notes.",
