      "origin": "Piedmont, northwest Italy",
      "summary": "Barbera is Piedmont's most widely planted red grape, valued for its deep colour, food-friendly high acidity, and low tannin, making it a versatile everyday wine as well as, in its best examples, a serious, structured red. It has traditionally played a supporting role to the more prestigious Nebbiolo in Piedmont but has gained increasing respect on its own merits, particularly from producers focused on old vines and careful winemaking. It is generally more approachable young than Nebbiolo, though top examples can age well.",
      "viticulture": "Barbera buds in the mid-season but ripens earlier and more reliably than Nebbiolo, making it a practical complement in vineyards that also grow the more demanding Nebbiolo. It is a vigorous, high-yielding vine that adapts well to a wide range of soils and is relatively resistant to many common fungal diseases, making it easier to grow than many of its Piedmontese neighbours. Yield control is important for quality, as overcropped vines produce simple, diluted wine, while lower yields concentrate its naturally high acidity and deep colour into more serious wine.",
      "characteristics": "Barbera produces deeply coloured wines with sour red cherry, plum, and blackberry fruit, and a hallmark of the variety is its very high, sometimes searing, natural acidity paired with notably low tannin. It is medium to full-bodied with moderate to high alcohol, and while simple examples emphasise fresh, juicy fruit, premium oak-aged versions develop vanilla, baking spice, and dark fruit depth that can rival more prestigious Piedmontese reds.",
