      "origin": "Piedmont, northwest Italy",
      "summary": "Dolcetto is an early-ripening Piedmontese red grape traditionally harvested before Barbera and Nebbiolo, producing deeply coloured, fruity, generally low-acid wines meant for relatively early drinking. Its name means 'little sweet one' in the local dialect, a reference to the natural sweetness of the ripe grapes rather than the finished wine, which is made dry. It plays a practical role in Piedmont's viticultural calendar, allowing growers to harvest an early-drinking wine while Nebbiolo continues ripening on the vine.",
      "viticulture": "Dolcetto buds relatively late but ripens notably earlier than both Barbera and Nebbiolo, which is why it is typically the first grape picked in the Piedmontese harvest, often in September. It has moderate vigour and is susceptible to coulure and downy mildew, and while it can be grown on a range of soils, it tends to be planted on cooler or less prime sites than Nebbiolo, since it does not need the same extended ripening window or heat exposure.",
      "characteristics": "Dolcetto produces deeply coloured, almost inky purple wines with dark fruit aromas of blackberry, black cherry, and plum, often accompanied by a characteristic note of licorice or dried herbs and a slightly bitter almond note on the finish. It is medium to full-bodied with notably low acidity for a Piedmontese red, moderate tannin that can show a rustic, slightly bitter edge, and moderate alcohol, making it softer and more immediately approachable than either Barbera or Nebbiolo.",
