      "origin": "Veneto, northeast Italy",
      "summary": "Corvina is the principal grape of the Valpolicella wine zone in Italy's Veneto region, forming the backbone of everything from light, everyday Valpolicella to the powerful, dried-grape Amarone della Valpolicella. Its name refers to the crow-like black colour of the grape skins, though the wines it produces are often relatively light in colour and tannin when made in a fresh style. Its suitability for the appassimento drying process makes it central to some of Italy's most distinctive and concentrated red wines.",
      "viticulture": "Corvina ripens relatively late and is a vigorous variety, traditionally trained on the pergola system in Valpolicella to shade the grapes and control ripening, though Guyot training is increasingly used for quality-focused vineyards. Its loosely packed bunches, partly a result of frequent millerandage during flowering, allow good air circulation, which is valuable both for disease resistance in the vineyard and for the appassimento process, where bunches are dried indoors for weeks or months after harvest. It performs best on well-drained hillside sites within Valpolicella, particularly in the classic zone, and generally requires blending partners to achieve full colour and structure.",
      "characteristics": "Fresh, unblended or lightly blended Corvina-based wines show sour cherry, red currant, and almond notes with high acidity, light to medium tannin, and relatively pale colour and light body. When dried through the appassimento process for Amarone, the concentrated grapes yield a completely different profile: raisin, dried fig, baked cherry, chocolate, and balsamic notes, full body, high alcohol, and considerably more tannin and extract, reflecting the intense concentration achieved by moisture loss during drying.",
      "winemaking": "Corvina is almost always blended, traditionally with Rondinella and Molinara and increasingly with small amounts of international varieties, to round out its structure and colour. For Amarone della Valpolicella and the sweet Recioto della Valpolicella, harvested bunches are dried on racks or in crates for weeks to months before pressing, concentrating sugars, flavours, and extract; the resulting wine is typically aged in oak. Valpolicella Ripasso involves re-fermenting a normal Valpolicella wine on the leftover skins and lees of Amarone, adding richness and body to a wine styled between simple Valpolicella and full Amarone.",
