      "origin": "East-central Italy (Abruzzo)",
      "summary": "Montepulciano is a workhorse red grape of east-central Italy, most famous as the sole variety behind Montepulciano d'Abruzzo. It produces deeply coloured, fruit-forward wines with soft tannins, and is often confused by students with the Tuscan town and wine Vino Nobile di Montepulciano, which is actually made from Sangiovese.",
      "viticulture": "Montepulciano is a vigorous, productive variety that buds early but ripens late, requiring a long warm growing season to reach full phenolic maturity; in cooler or shorter seasons it can struggle to ripen fully, leaving green tannins. It is naturally high-yielding and is often cropped generously for everyday wine, though quality-focused producers restrict yields for greater concentration. The variety is prone to coulure in poor flowering conditions and to bunch rot in humid years given its tendency toward tight, compact bunches, but it generally has good resistance to drought and performs well on the hillside sites of Abruzzo and the Marche.",
      "characteristics": "Montepulciano typically shows dark, brambly black-fruit character - black cherry, blackberry, and plum - with notes of dried herbs, black pepper, and sometimes a rustic, earthy or leathery edge. Colour is usually deep and youthful. It has naturally high acidity and notably soft, approachable tannins for a full-bodied variety, with medium-to-high alcohol; warmer sites and lower yields push the fruit toward riper, jammier, more concentrated expressions, while high-yield examples are lighter, tarter, and more simply fruity.",
      "winemaking": "Most Montepulciano is vinified for early drinking with moderate maceration to preserve soft tannin and fresh fruit, often seeing little or no oak, or brief time in large neutral botti. Premium bottlings (including single-vineyard or Riserva wines) undergo longer maceration and ageing in barrique or larger casks to add structure and complexity. The grape is also used to make Cerasuolo d'Abruzzo, a deeply coloured rosato made by limited skin contact, and rustic old-vine examples can show real depth and age-worthiness. It is essentially always varietal in its DOC/DOCG expressions and should not be confused with Sangiovese-based Vino Nobile di Montepulciano, a classic naming trap.",
