      "origin": "Southern Italy (Campania/Basilicata)",
      "summary": "Aglianico is considered one of Italy's noblest red grapes, often called the 'Barolo of the South' for its structure and ageing potential. It produces deeply coloured, high-tannin, high-acid wines, particularly distinctive when grown on the volcanic soils of Basilicata and Campania.",
      "viticulture": "Aglianico is a late-budding, very late-ripening variety, often harvested in late October or even November, which allows it to retain high acidity while accumulating tannin and colour. It performs best on volcanic soils at moderate-to-high altitude, where warm days and cool nights preserve freshness; on Mount Vesuvius and Monte Vulture its extended hang time under continued sunshine and diurnal swings is key to balanced ripeness. The variety is moderately vigorous with naturally thick skins, giving good resistance to rot, though its late ripening leaves it vulnerable to autumn rains in less favourable vintages.",
      "characteristics": "Aglianico wines show dark, savoury black fruit - black cherry, plum, and blackberry - alongside notes of tar, leather, dried herbs, tobacco, and often a smoky, mineral, volcanic edge. The wines are typically full-bodied with high tannin, high acidity, and medium-to-high alcohol, and can show a firm, sometimes austere structure in youth that softens with bottle age into more savoury, dried-fruit and leather notes. Cooler, higher-altitude sites and younger vines yield more red-fruited, floral, and taut wines, while warmer, lower sites give riper, richer, more brooding examples.",
      "winemaking": "Because of its high tannin and acidity, Aglianico is generally given a relatively long maceration to fully soften and integrate tannins, followed by extended ageing, traditionally in large old Slavonian oak botti, though many modern producers now use French barriques for a portion of the blend to add spice and polish. It is most often vinified as a varietal wine and is capable of long bottle ageing, with top examples needing a decade or more to open fully. Some lighter, fruitier styles are made for earlier drinking with shorter maceration and less oak influence.",
