      "summary": "Nero d'Avola is Sicily's most important native red grape, producing everything from soft, juicy, easy-drinking reds to concentrated, age-worthy wines. It has become a flagship variety for modern Sicilian wine, prized for its ripe dark fruit and approachable structure.",
      "viticulture": "Nero d'Avola is a vigorous variety suited to warm, dry Mediterranean climates, budding mid-season and ripening in the mid-to-late part of the harvest window. It performs well across a range of Sicilian soils and altitudes, with high-altitude and coastal sites (such as around Noto and Vittoria) providing valuable diurnal temperature variation to preserve acidity and aromatic freshness in an otherwise hot climate. The variety can be prone to uneven ripening (millerandage) and needs careful canopy management in very hot sites to avoid raisining and excessive alcohol; drought tolerance is generally good, suiting Sicily's dry summers.",
      "characteristics": "Typical Nero d'Avola shows ripe black and red fruit - plum, black cherry, and blackberry - with notes of licorice, dried herbs, and sometimes a light spiciness. The wines are usually medium-to-full bodied with soft-to-medium tannins, moderate-to-high acidity, and medium-to-high alcohol reflecting Sicily's warm climate. Cooler or higher-altitude sites give fresher, more red-fruited and floral wines with brighter acidity, while warmer, lower-yield examples are riper, darker-fruited, and more concentrated, occasionally with jammy or dried-fruit character.",
      "winemaking": "Nero d'Avola is made in a wide range of styles: light, fruity, unoaked or lightly oaked wines for early drinking are common, alongside more serious, oak-aged examples using French barrique for structure and spice. It is often blended with international varieties such as Syrah or Cabernet Sauvignon, or with other Sicilian grapes like Frappato, most famously in Cerasuolo di Vittoria, where its structure balances Frappato's lighter, more perfumed character. Maceration times vary with intended style, from short and gentle for fresh, juicy wines to longer and more extractive for age-worthy bottlings.",
