      "origin": "Spain (likely Valencia/Alicante region)",
      "summary": "Mourvèdre (called Monastrell in Spain and Mataro in parts of Australia and California) is a thick-skinned, late-ripening grape producing dark, powerful, tannic wines, essential to southern Rhône blends and the backbone of many Spanish reds. It needs significant heat to ripen fully, thriving in warm, dry Mediterranean climates.",
      "viticulture": "Mourvèdre/Monastrell buds late and ripens very late, requiring long, hot growing seasons to achieve full phenolic ripeness, which limits it to warm Mediterranean climates. It is naturally drought-tolerant and well suited to poor, dry soils, performing particularly well on bush vines in low-vigour sites, but it is sensitive to wind and can suffer if water stress becomes too severe or if planted in cooler sites where it fails to ripen, giving green, reductive characters. It is also susceptible to powdery mildew and grape moths, and its late ripening leaves it exposed to autumn rain risk in marginal areas.",
      "characteristics": "The variety produces deeply coloured, full-bodied wines with dark fruit - blackberry, plum, and black cherry - alongside characteristic notes of game, leather, black pepper, and a distinctive gamey/animal or 'barnyard' funk, especially notable in reduction. Tannins are high and often firm/rustic, acidity is medium, and alcohol tends to be high given the heat needed for ripening. Cooler or higher-altitude sites within its range give more red-fruited, peppery, and floral wines, while very warm, low-yield old-bush-vine sites (such as in Bandol or Jumilla) give the most concentrated, powerful, savoury expressions.",
      "winemaking": "Mourvèdre/Monastrell typically undergoes relatively long maceration to extract its considerable colour and tannin, and is often aged in a mix of large old oak foudres and smaller barrels to soften tannin without adding excessive new oak character. It is a key blending partner in southern France, most famously in the GSM blend (Grenache-Syrah-Mourvèdre) of the southern Rhône and Bandol (where it must form the majority of the blend), and in Spain it is used both varietally (Jumilla, Yecla) and in blends. It can also be vinified as a fresh, fruity rosé and, less commonly, as a component in fortified or late-harvest sweet styles.",
