      "origin": "Aragón, Spain",
      "summary": "Carignan is a historically high-yielding, deeply coloured, tannic grape once ubiquitous in southern France and Spain for bulk wine, now increasingly valued from old, low-yielding vines for concentrated, characterful reds. Its reputation has shifted markedly from a workhorse blending grape to a source of prized old-vine wines.",
      "viticulture": "Carignan is a late-budding, late-ripening variety that is naturally very vigorous and high-yielding, which historically made it popular for bulk production but which, unless yields are restricted, produces light-coloured, tart, tannic, and rather neutral wine. It prefers warm, dry Mediterranean climates and performs best on poor, low-fertility soils and as old, dry-farmed bush vines, where restricted vigour concentrates flavour and colour considerably. The variety is susceptible to powdery mildew, grape moths, and rot in humid conditions, and its late ripening can be a liability in cooler or shorter seasons.",
      "characteristics": "Young-vine, high-yield Carignan tends to be light-to-medium bodied with high acidity, high tannin, and rather neutral red-fruit character, sometimes described as tart and rustic. Old-vine, low-yield Carignan, by contrast, produces much more concentrated wines with dark fruit (blackberry, black plum), notes of garrigue herbs, licorice, and spice, fuller body, and riper, better-integrated tannins. Across expressions the variety retains notably high, fresh acidity and firm tannic structure, with alcohol levels varying with yield and site, generally higher in low-yield old-vine examples.",
      "winemaking": "Because young or high-yield Carignan can be harsh, it has traditionally been blended to soften its acidity and tannin, playing a supporting role in southern French blends such as those of the Languedoc-Roussillon and Corbières alongside Grenache, Syrah, and Mourvèdre. Increasingly, producers seek out old, low-yielding bush vines (some over 50-100 years old) for varietal or near-varietal bottlings, often using carbonic or semi-carbonic maceration to soften tannin and highlight fruit, alongside more structured, oak-aged approaches. In Spain it is known as Mazuelo/Samsó and used as a minor blending component in Rioja and Priorat; in Sardinia (as Carignano del Sulcis) it produces distinctive, often old-vine varietal wines.",
