      "origin": "Bordeaux, France",
      "summary": "Petit Verdot is a small-berried, deeply coloured, tannic grape traditionally used in tiny proportions in Bordeaux blends to add structure, colour, and spice. It ripens very late and is unreliable in Bordeaux's cooler vintages, but has found more consistent success as both a blending and varietal grape in warmer New World regions.",
      "viticulture": "Petit Verdot buds relatively early but ripens very late, often the last of the Bordeaux varieties to be picked, which historically made it an unreliable component in Bordeaux given the region's marginal climate and risk of autumn rain before full ripeness. It requires a long, warm growing season and performs much more consistently in warmer climates such as parts of Spain, Australia, California, and Chile, where it ripens fully and reliably each vintage. The variety is relatively vigorous but produces small, thick-skinned berries with a high skin-to-juice ratio, giving intense colour and tannin; it has reasonable disease resistance but its late ripening remains its key viticultural challenge.",
      "characteristics": "Petit Verdot produces intensely coloured wines with a distinctive aromatic profile of violets, blackberry, black plum, and often notes of pencil shavings, graphite, and spice, along with a herbal or floral lift. It is typically full-bodied with high tannin and high acidity, and when fully ripe carries notable alcohol; in underripe conditions it can show harsh, green, or overly herbaceous character. Warmer-climate examples tend to be riper, more fruit-forward, and softer in tannin than the more austere, structured character it can show in cooler vintages of Bordeaux.",
      "winemaking": "In Bordeaux, Petit Verdot is used in very small proportions (often a few percent) blended into Cabernet Sauvignon-based wines to reinforce colour, tannin, and aromatic spice/floral lift, particularly in warm, ripe vintages. In warmer New World regions it is increasingly bottled as a varietal wine or used at higher proportions in blends, typically given significant oak ageing (often new French oak) to help tame and integrate its considerable tannin. Because of its intensity, winemakers often manage extraction carefully to avoid excessive astringency, and the grape's small berries and thick skins mean it responds well to selective, ripe-fruit sourcing.",
