      "origin": "South Africa (bred 1925)",
      "summary": "Pinotage is South Africa's signature grape, a deliberate crossing bred to combine the finesse of Pinot Noir with the productivity and disease resistance of Cinsault (then known locally as Hermitage). It produces wines ranging from bright, fruity styles to rich, full-bodied, oak-aged examples, and remains a point of national pride and identity for South African wine.",
      "viticulture": "Pinotage is a genuine crossing of Pinot Noir and Cinsault, bred by Professor Abraham Izak Perold at Stellenbosch University in 1925. It buds and ripens in a mid-season window, is relatively vigorous, and generally more productive and disease-resistant than Pinot Noir, one of the original goals of the crossing. It performs well in South Africa's warm, dry-summer climate, tolerating heat and drought reasonably well, though it can be prone to producing high yields that dilute concentration if not carefully managed, and it is susceptible to a fermentation-related off-note (isoamyl acetate, a banana/nail-polish-remover aroma) if handled poorly, particularly with certain yeast strains and high fermentation temperatures.",
      "characteristics": "Pinotage typically shows dark fruit - plum, blackberry, and black cherry - along with distinctive notes of that can range from bright red fruit and banana in youthful, fruit-driven styles, to smoky, earthy, tarry, or rubbery notes in more extracted or heavily oaked examples. Body is medium-to-full, tannins are medium-to-high, and acidity is moderate; alcohol tends to be medium-to-high given South Africa's warm growing conditions. Style varies enormously by winemaking choice: fresh, juicy, lighter styles emphasise red fruit and easy drinking, while old-vine, low-yield, and heavily oaked 'Cape Blend'-style wines show much greater concentration, spice, and structure.",
      "winemaking": "Pinotage is made in a very wide range of styles, from simple, fruity, easy-drinking reds with light or no oak, to serious, concentrated, oak-aged wines using new French oak (sometimes including specific coopering techniques developed to manage its aromatic intensity). It is a key component of the 'Cape Blend', an unofficial but recognised South African style blending Pinotage with Bordeaux varieties (Cabernet Sauvignon, Merlot) and/or Rhône varieties (Syrah), and is also used to make sweet, fortified 'Pinotage port-style' wines and even coffee-toned dessert wines in some cases. Careful control of fermentation temperature and yeast selection is important to avoid the banana/nail-polish aromas the variety can develop if mishandled.",
