      "origin": "Naoussa, Macedonia, Greece",
      "summary": "Xinomavro is northern Greece's most important red grape, producing structured, high-tannin, high-acid wines often compared to Nebbiolo for their combination of power and elegance. Its name translates literally to 'acid-black', reflecting its two defining characteristics.",
      "viticulture": "Xinomavro buds relatively early but ripens late, and it is well suited to the cooler, more continental climates of northern Greece such as Naoussa and Amyndeon, where a long, gradual ripening period preserves its hallmark high acidity. It performs well on a range of soils but shows particular character on clay and sandy soils in different subzones, and it is a relatively vigorous variety requiring careful canopy and yield management to avoid overcropping, which can dilute its concentration. The variety is susceptible to downy mildew and can suffer from uneven ripening, but its late ripening and retained acidity make it well suited to cooler high-altitude or northerly sites.",
      "characteristics": "Xinomavro wines show a distinctive profile of red fruit (tomato, red cherry, cranberry) alongside notes of olive, dried herbs, and, with age, a hallmark savoury, tomato-leather-spice complexity that has drawn frequent comparisons to Nebbiolo and Barolo. The wines are typically medium-to-full bodied with high tannin and notably high acidity, and moderate alcohol, giving them a firm, structured, age-worthy profile even though colour can be relatively pale for such a tannic grape. Young Xinomavro can be quite austere and tannic, requiring bottle age (often a decade or more for top examples) to soften into its more complex, savoury, tertiary-noted mature state.",
      "winemaking": "Xinomavro is typically vinified with careful attention to managing its high tannin, often via moderate maceration and extended oak ageing (both large old oak and smaller French barriques are used) to soften structure and add complexity. It is most commonly made as a varietal wine, especially in Naoussa, though it is sometimes blended with international varieties or other Greek grapes in more modern bottlings. Its high acid and tannin profile also makes it suitable for extended bottle ageing before release, and top producers frequently hold back wines for additional cellar time to allow the tannins to resolve.",
