      "viticulture": "Agiorgitiko buds and ripens in a mid-to-late season window and is a relatively adaptable, reasonably vigorous variety that performs well across a range of altitudes and soils in Nemea, from warmer lower-altitude sites giving riper, fuller wines to cooler, higher-altitude vineyards giving fresher, more elegant, aromatic expressions. It has good drought tolerance and reasonable disease resistance, and its versatility across mesoclimates within Nemea is part of what allows producers to make such a wide stylistic range from the grape. It is generally less prone to the high-acid, high-tannin extremes of Xinomavro, making it easier to manage in the vineyard for consistent ripeness.",
      "characteristics": "Agiorgitiko typically shows ripe red and black fruit - red cherry, plum, and blackberry - often with notes of sweet spice, dried herbs, and sometimes a chocolatey or floral lift, especially in riper or oak-aged examples. Body ranges from medium (in fresh, unoaked styles) to full (in riper, oak-matured examples), tannins are generally soft-to-medium and approachable, acidity is medium, and alcohol is medium-to-high, particularly from warmer, lower-altitude sites. Higher-altitude Nemea sites give more elegant, fresher, red-fruited wines with brighter acidity, while warmer sites and extended oak ageing yield richer, darker-fruited, more structured wines.",
