      "viticulture": "Blaufränkisch buds mid to late and ripens late, needing warm, well-exposed sites to fully ripen its naturally high acidity and tannin. Its tight bunches make it susceptible to botrytis bunch rot in damp conditions, and it shows moderate to high vigor, performing best on well-drained soils. It is relatively cold-hardy compared to many fine red varieties, which has helped it succeed as far afield as Washington State, where it is grown as Lemberger.",
