      "summary": "Gaglioppo is the principal red grape of Calabria in Italy's deep south, most closely associated with the Cirò DOC. It produces deceptively pale-coloured wines that carry surprisingly high tannin and alcohol, reflecting its Mediterranean, sun-baked origins.",
      "viticulture": "Gaglioppo thrives in Calabria's hot, dry Mediterranean climate and is traditionally trained as low bush vines (alberello) on south-facing hillsides such as those around Cirò, which provide the heat and drainage it needs. It buds early but ripens very late, reliably accumulating high sugar levels given the region's consistent summer heat. The vine is naturally vigorous and needs canopy and yield management to avoid diluting quality, but disease pressure is generally low in Calabria's dry conditions; drought stress on shallow hillside soils is a bigger concern than fungal disease.",
      "characteristics": "Despite its high tannin, Gaglioppo yields wines of relatively pale ruby colour because of a high seed-to-pulp ratio and modest anthocyanin content, a paradox sometimes compared to Nebbiolo. Typical aromas include red cherry, wild strawberry, dried oregano and other Mediterranean herbs, leather and orange peel, moving toward tar and dried fruit with age. Wines are high in tannin and acidity, medium-to-full in body, and typically high in alcohol.",
      "winemaking": "Traditional Cirò winemaking involved extended maceration to pull tannin from the thick seed mass, often with oxidative handling that left wines pale and tawny at the rim; modern producers increasingly use temperature-controlled fermentation and gentler extraction for fresher fruit. Ageing traditionally takes place in large old Slavonian-style botti, though some producers now use barriques. Gaglioppo is also the base of Cirò Rosato, a historically important pale pink wine, and is usually vinified as a high percentage or 100% varietal wine under Cirò DOC rules.",
