      "origin": "Montenegro and the western Balkans",
      "summary": "Vranac is Montenegro's flagship red grape and the most widely planted variety in the country, also important in North Macedonia and Serbia. It produces deeply coloured, full-bodied, dark-fruited wines that range from everyday reds to serious oak-aged bottlings.",
      "viticulture": "Vranac grows in the warm continental climate typical of the western Balkans, ripening mid-to-late season and showing good vigour with generally reliable, generous yields. It adapts to a range of soils and is relatively resilient to some common fungal diseases, though overcropping can dilute its natural concentration if not controlled. Some of its most important plantings sit on the plain around Lake Skadar near Podgorica, Montenegro, where warm days and cooling lake influence support full ripening.",
      "characteristics": "Vranac produces wines of deep, dense purple-black colour with aromas of blackberry, blackcurrant, plum and dark chocolate, often gaining spice and dried-fruit notes with maturity. It is typically full-bodied with high tannin, moderate-to-high acidity and high alcohol, giving it good structure for ageing in its more serious expressions.",
      "winemaking": "Everyday Vranac is often made in a fruit-forward, lightly oaked or unoaked style, while premium bottlings see extended maceration and ageing in large oak or barrique to soften and integrate the grape's substantial tannin. It is sometimes blended with international varieties such as Cabernet Sauvignon or Merlot to add complexity, and is also vinified into rosé.",
