      "color": "red",
      "synonyms": [],
      "origin": "Dalmatian coast, Croatia",
      "summary": "Plavac Mali is Croatia's most celebrated native red grape, grown on the steep, sun-drenched coastal vineyards of Dalmatia. It produces powerful, high-alcohol, tannic wines, with the terraced sites of Dingač and Postup on the Pelješac peninsula regarded as its finest expressions.",
      "viticulture": "DNA profiling published in 2001 by Croatian researchers Edi Maletić and Ivan Pejić together with UC Davis's Carole Meredith established Plavac Mali as a natural crossing of Crljenak Kaštelanski (the grape known internationally as Zinfandel/Tribidrag/Primitivo) and the local variety Dobričić. It is a late-budding, very late-ripening vine that demands the intense sun exposure of steep, south-facing, stony coastal slopes such as Dingač and Postup, where it is traditionally hand-farmed on narrow terraces. Yields are naturally low and can be uneven due to poor fruit set (millerandage), and the vine needs the reflected heat and drainage of these marginal sites to ripen fully.",
      "characteristics": "Plavac Mali produces deeply coloured, ruby-to-purple wines with ripe blackberry, black cherry, dried fig and Mediterranean herb (garrigue) character. It is typically full-bodied with high tannin, high alcohol given its long hang time under intense sun, and medium-to-high acidity.",
      "winemaking": "Traditional examples can be rustic, with pronounced alcohol and tannin from long maceration, while premium wines from Dingač and Postup undergo careful extraction and ageing in large Slavonian oak or barrique to tame the tannin. It is almost always made as a varietal wine rather than blended, reflecting its status as Croatia's signature red.",
