      "origin": "Balkans, historically dominant in Hungary",
      "summary": "Kadarka was once Hungary's most widely planted red grape and the historic backbone of Egri Bikavér ('Bull's Blood'), but its unreliable cropping caused plantings to collapse through the twentieth century. It produces pale, spicy, high-acid wines with a character sometimes likened to a rustic Pinot Noir or Gamay.",
      "viticulture": "Kadarka grows in the moderate-to-warm continental climate of the Carpathian Basin, budding and ripening late. It is notoriously unreliable in the vineyard: thin skins and tight bunches make it highly susceptible to botrytis bunch rot, and it is prone to poor fruit set (coulure) in cool or wet flowering conditions, leading to inconsistent yields from year to year. These traits caused twentieth-century growers to favour steadier varieties such as Kékfrankos, though it performs best on warm, well-drained sites that help it ripen and avoid rot.",
      "characteristics": "Kadarka gives pale ruby wines with red cherry, cranberry and raspberry fruit alongside a distinctive white pepper and spice character. Wines are light-to-medium bodied, high in acidity, moderate in tannin and moderate in alcohol, generally favouring freshness over power.",
      "winemaking": "Historically, Kadarka was a key component of Egri Bikavér, blended alongside Kékfrankos and other varieties, and it is traditionally handled with light extraction and little or no new oak to preserve its delicate, spicy character. In Bulgaria the same grape, known as Gamza, has long been used for everyday reds. A small number of producers now champion old-vine Kadarka as a serious varietal wine, reviving interest in a grape once nearly abandoned.",
